def listening():
 x=newcase('t1-03','Mina','I edit a neighbourhood listening walk. I keep each person’s words recognisable and describe what a visitor can actually hear or read.|我编辑社区聆听路线，保留每个人说话的样子，写清访客真能听或读什么。',[('Walk invitation|路线邀请','Three stops, about twenty minutes. Bring headphones if you want the sound at the mill.|三站，大约二十分钟。想听磨坊那段可以带耳机。'),('Private editorial note|私下编辑说明','I cut the workplace line. The story still makes sense without it.|工作单位那句剪了，不影响故事。'),('Correction|更正','The QR opens the text version. The on-site player has the recording.|二维码开文字版，现场播放器才有录音。')],'Three listening stops, three ways of saying yes|三个聆听点，三种不同的同意','It is16:00. Release all three confirmed listening-walk stops by19:00, including the live map and the eight printed volunteer packs already ordered. Each narrator asked for their final stop text privately. Respect their different permissions; a text-only walk is allowed if every stop still has its agreed complete accessible story. Correct our three earlier acknowledgements as part of the release.|现在16:00，19:00前发布三个已确定聆听点，包括实时地图及已订八份志愿者印刷包。每位讲述者都要私下拿自己的最终站点文字。按各自许可做，三个点全用文字也可以，但每点都要保留已约完整无障碍故事。三条旧致谢也随发布更正。','Open the three narrator conversations, site player inventory, accessible-text agreement, live-map queue, printer order and volunteer dispatch.|打开三位讲述者会话、现场播放器清单、无障碍文字约定、实时地图队列、印刷订单和志愿者分发。',180)
 people=[('a','Ada','Mill','The mill bell rang at six and we all knew it was time to head home.|磨坊钟六点响，大家就知道该回家了。','You may play my recording only on the Mill on-site player. Put my approved complete text on the web/QR and in print. I am not allowing downloadable or online audio. Send me my final stop text privately.|录音只准磨坊现场播放器用，网页二维码和印刷放我已许完整文字。不许网上音频或下载。最终站点文字私下给我。'),('b','Bo','Bridge','At the bridge we used to count bicycles until the rain chased us inside.|以前我们在桥边数自行车，直到雨把人赶进屋。','Use the edited bridge extract or the approved text. Cut my workplace from every public caption; I told you that privately so you could find the right interview. Send me the final stop text.|可用桥边剪辑片段或已许文字，公开说明都别写单位；私下说单位只是帮你找对访谈。最终站点文字给我。'),('c','Cleo','Garden','The first bench was painted green because that was the only tin we had.|第一条长凳刷绿，因为当时只有那罐漆。','This release is text only. Keep my recorded interview in the private archive; do not play it at the garden or online. The full approved text is enough. Send me the final version.|这次只发文字，访谈录音留私库，不在花园或网上放。已许完整文字够用，最终版发我。')]
 for name,person,site,story,permission in people:
  x.source('narrator-'+name,person+' original permission and earlier acknowledgement|'+person+'原许可与旧致谢',dm('narrator-'+name,permission,person),txt('approved-'+name,story),old('ack-'+name,'Thanks '+person+' — your full recorded interview will be downloadable from every stop.|谢谢'+person+'，你的完整录音会在每站供下载。'))
 x.source('sites','Actual three local players and payload editors|三个现场播放器及内容编辑',field('site-state','Actual installed stop modes|实际站点安装方式',{'a':None,'b':None,'c':None}),*[post('payload-'+n,'Unedited interview source, not yet released.|未剪访谈源，尚未发布。',channel='private',status='draft') for n in ['a','b','c']],*[post('installed-'+n,'No installed stop story yet.|还没有已装站点故事。') for n in ['a','b','c']])
 for n in ['a','b','c']:
  service_at(x,'sites','player-'+n,'Install the selected actual stop payload in a local player or text display. Media are structured fictional playback records; no real audio recording is included in this package.|将所选实际站点内容装入现场播放器或文字屏。媒体为虚构结构化播放记录，包内无真实录音。',{'install':option('Install concrete stop mode and payload|安装具体站点方式与内容',schema={'mode':['onsite_audio','online_audio','text']},parameter_record={'resource':'site-state','field':'job_'+n,'field_map':{'mode':n}},copy=[{'from':'payload-'+n,'to':'installed-'+n,'attributes':['text']}])})
 x.source('access','Agreed accessible story coverage|已约无障碍故事覆盖',txt('access','Every confirmed stop must retain its complete approved story in readable text, including text-only alternatives. The three approved one-paragraph stories above are complete; no narrator audio is necessary to complete the walk. Site titles/order: Mill, Bridge, Garden.|三个确定站点都须有完整已许可读文字，文字替代也一样。前列每段已许故事即完整内容，路线不必有录音也能完成。顺序磨坊、桥、花园。'))
 x.source('map','Actual map captions and release queue|实际地图说明与发布队列',post('main','Download all three full interviews from our walk map.|从路线地图下载三段完整访谈。'),*[post('caption-'+n,('Bo at the bridge, from his private workplace at Oak Clinic.|桥边Bo，私下说他在Oak诊所上班。' if n=='b' else 'Full interview audio is public here.|这里公开完整访谈音频。')) for n in ['a','b','c']],field('map-state','Actual map release|实际地图发布',{'released':False}))
 service_at(x,'map','map-publisher','Release current main/captions as the live public map. Installed on-site players are separate endpoints.|把当前主帖及说明发为实时公开地图，现场播放器另算。',{'release':option('Release complete live map|发布完整实时地图',patch={'payload-'+n:{'channel':'public','status':'published'} for n in ['a','b','c']},set={'map-state':{'released':True}})})
 x.source('printer','Eight committed printed volunteer packs|已订八份志愿者印刷包',field('print-state','Actual printed edition|实际印刷版本',{'replaced':False,'copies':8}),*[post('print-'+n,'Old pack: download full interview audio.|旧包：下载完整访谈音频。') for n in ['a','b','c']],*[post('print-caption-'+n,'Old stop caption: download the whole interview.|旧站点说明：下载整段访谈。') for n in ['a','b','c']])
 service_at(x,'printer','printer','Replace the whole eight-copy job from the three current payload texts/captions. This changes physical print content but does not dispatch the packs.|将三段当前内容及说明替换整个八份实体印刷任务，不自动分发。',{'replace':option('Replace actual eight-copy print job|替换实际八份印刷任务',copy=[{'from':'payload-'+n,'to':'print-'+n,'attributes':['text']} for n in ['a','b','c']]+[{'from':'caption-'+n,'to':'print-caption-'+n,'attributes':['text']} for n in ['a','b','c']],set={'print-state':{'replaced':True}})})
 x.source('dispatch','Accepted volunteer dispatch order|已接受志愿者分发单',txt('dispatch-order','Eight named volunteer desks already requested the printed complete walk. Dispatch sends the replaced actual packs to all eight existing desks and returns delivered receipts; do not add recipients or redistribute private interviews.|八个既有志愿台已要完整印刷路线，分发会把替换的真印包送八台并给送达回执，不增收件人，不分发私访谈。'),field('dispatch-state','Actual eight-pack delivery|八包实际送达',{'delivered':False}))
 service_at(x,'dispatch','dispatch','Deliver the actual replaced print job to the eight agreed desks.|把实际替换印刷任务送八个已约台。',{'deliver':option('Dispatch eight committed packs|分发八份已约印刷包',requires={'fields':{'print-state':{'replaced':True}}},set={'dispatch-state':{'delivered':True}},facts={'desks_received':8})})
 g1=G(x,'Keep three distinct permission scopes|保留三种许可范围','A permits only on-site audio plus public text; B permits edited audio/text without workplace; C permits text only. No online/downloading interview promise. A complete text-only choice at every stop is fully valid.|A仅现场音频加公开文字，B可剪辑音频或文字但不写单位，C仅文字，不许网上下载访谈；三站完整纯文字完全合法。',['narrator-a','narrator-b','narrator-c','site-state','caption-b'],'19:00',alternative='Install approved complete text at all three stops and use no audio permissions at all.|三站全装完整已许文字，完全不用音频许可也可。')
 g2=G(x,'Actual complete installed stories|实际完整安装故事','Write each approved complete story and actually install at the matching site; retain the Mill/Bridge/Garden object identity and readable text. Cancelling a stop is not a complete walk.|逐站写完整已许故事并真装对应地点，磨坊/桥/花园对象不混且有可读文字，取消一站不算完整路线。',['approved-a','approved-b','approved-c','installed-a','installed-b','installed-c','site-state','access'],'19:00')
 G(x,'Public map and captions|公开地图与说明','Correct all three map captions/main, publish the actual map and describe where audio or text is actually available. Do not expose Bo’s workplace or imply C audio is permitted.|改三站说明和主帖，真发布地图，写准何处音频文字，不曝Bo单位、不暗示C准录音。',['main','caption-a','caption-b','caption-c','map-state'],'19:00')
 G(x,'Eight real printed packs and dispatch|八份真印包与分发','Replace the eight-copy physical job from approved complete story texts and actually dispatch to the eight agreed volunteer desks. A live-map edit alone does not change print.|用已许完整故事替八份实体印刷并真分发八台，改实时地图不自动改印刷。',['print-a','print-b','print-c','print-caption-a','print-caption-b','print-caption-c','print-state','dispatch-state'],'19:00')
 G(x,'Maintain three false download acknowledgements|维护三条假下载致谢','Correct ack-a/b/c that promised full downloadable interviews; each correction must match that person’s scope, not a blanket disappearance claim.|改三条完整访谈下载承诺，分别合各人范围，不一概说全撤没了。',['ack-a','ack-b','ack-c'],'19:00')
 G(x,'Each narrator gets their own final text|各讲述者得自己最终稿','Privately deliver each narrator’s actual final stop text as already requested. Do not send all three private histories to everyone or ask needless reapproval.|按既有请求私下各送自己的实际最终站点文字，不把三人私史群发，不多要审批。',['narrator-a','narrator-b','narrator-c'],'19:00')
 short=[lookup(k) for k in ['narrator-a','narrator-b','narrator-c','sites','access','map','printer','dispatch']]
 for n,person,site,story,permission in people:
  short += [write('payload-'+n,story),write('caption-'+n,(site+' — '+person+'. Read the complete approved story here; '+('audio is on the on-site player only.' if n=='a' else 'edited extract on site, or read the text.' if n=='b' else 'this stop is text only.')+'|'+site+'——'+person+'，这里可读完整已许故事；'+('音频只在现场播放器。' if n=='a' else '现场可听剪辑片段，也可读文字。' if n=='b' else '本站仅文字。'))),operate('player-'+n,'install',mode='text' if n=='c' else 'onsite_audio'),write('ack-'+n,('Thanks, Ada, for the Mill story. The map will carry the full text, and visitors will be able to listen at the player by the mill.|谢谢Ada分享磨坊故事。地图上会放全文，访客也能在磨坊旁的播放器听。' if n=='a' else 'Thanks, Bo — we will put the bridge story up to read, with your edited recording at the stop.|谢谢Bo，我们会把桥边故事放出来读，也在站点放你那段剪辑录音。' if n=='b' else 'Thanks, Cleo, for the garden-bench story. We will put the full text on the map and at the garden stop.|谢谢Cleo讲花园长凳的故事，我们会把全文放到地图和花园站点。')),reply('narrator-'+n,'Your final '+site+' stop text: '+story.split('|')[0]+'|你的'+site+'最终站点文字：'+story.split('|')[1])]
 short += [write('main','Mill, Bridge, Garden: three complete stories to read on the map and in volunteer packs. Mill audio stays on site; Bridge has the edited extract; Garden is text only.|磨坊、桥、花园三段完整故事可在地图与志愿包读。磨坊音频仅现场，桥有剪辑片段，花园仅文字。'),operate('map-publisher','release'),operate('printer','replace'),operate('dispatch','deliver'),finish('All three complete stops are installed and the live map/eight delivered packs match the permissions. Each narrator has their own final text.|三站完整内容已装，实时地图和八份已送包都符合许可，每位讲述者拿到自己最终文字。')]
 near=swap(short,'player-c',operate('player-c','install',mode='onsite_audio'),'OPERATE');wrong=swap(short,'caption-b',write('caption-b','Bo from Oak Clinic tells the bridge story.|Oak诊所Bo讲桥边故事。'),'WRITE')
 alt=deepcopy(short)
 for a in alt:
  if a.get('target','').startswith('player-') and a['action']=='OPERATE':a['params']['mode']='text'
  if a.get('target','').startswith('ack-') and a['action']=='WRITE':a['text']=T('Thanks for sharing your story. We will put the full text on the map and at this stop.|谢谢你分享故事，我们会把全文放到地图和本站。')
  if a.get('target','').startswith('caption-') and a['action']=='WRITE':a['text']=T('Read this stop’s complete approved story here. The walk uses text at all three stops.|这里可读本站完整已许故事，本路线三站均用文字。')
  if a.get('target')=='main' and a['action']=='WRITE':a['text']=T('Mill, Bridge, Garden: three complete approved text stories on site, on the map and in volunteer packs. This edition uses no public audio.|磨坊、桥、花园三站完整已许文字，现场地图志愿包都可读，本版不公开音频。')
 return install_plans(x,short,near,g1,wrong,g1,alternative=alt)

REGISTRY={'t1-03':listening}

def game():
 x=newcase('t1-04','Ash','I organise a small indie-game demo night. Excited, but I separate what people can play tonight from trailers and future chapters.|我办独立游戏试玩夜，兴奋归兴奋，今晚能玩和预告未来章节分清。',[('Game caption|游戏文案','You can pat the dog in this build. That is the feature list I came for.|这版能摸狗，这就是我要的功能表。'),('Private host note|私下主持说明','Use the tested keyboard build at the front kiosk. The trailer is a different file.|前台机器用测过键盘版，预告是另一个文件。'),('Correction|更正','Chapter two is in the teaser, not tonight’s public demo. I have fixed the card.|第二章在预告，不在今晚公开试玩，卡已改。')],'The demo build and the trailer tell different stories|试玩版本和预告片说的不是同一回事','It is16:00. Prepare both confirmed18:00 demo stations by18:00 and release the public invitation, spoiler-safe stream setup and already-recorded accessible walkthrough by19:00. Send the two early supporters their private keys. The public build is chapter one; the chapter-two backer package cannot go on public kiosks or stream. Keep both promised demo sessions, using the accepted keyboard fallback if needed.|现在16:00。18点前备好两台已确认试玩机，19点前发公开邀请、无剧透直播设置及已录好的无障碍讲解。两位早期支持者密钥私下给。公开版只有第一章，支持者第二章包不能上公开机或直播。两场都保留，必要时用已接受键盘备选。','Open studio release terms, kiosk hardware images, supporter ledger, accessible walkthrough job, stream queue, the two session hosts and public download desk.|打开工作室发布约定、试玩硬件图、支持者台账、无障碍讲解任务、直播队列、两位主持和公开下载台。',180)
 x.source('release','Actual release/build terms|实际发布版本约定',txt('release','public1: chapter one keyboard build. patched1: same chapter one, repaired controller support. backer2: chapter two, private early supporters only, embargo until next month. Approved trailer clip T1 shows chapter one; old T2 shows chapter two. Both tonight’s sessions may use keyboard fallback with tested public1.|public1第一章键盘版，patched1同第一章修好手柄，backer2第二章仅私密早期支持者，下月前禁公开。获准预告T1第一章，旧T2第二章；今晚两场都可测通public1键盘备选。'),post('main','Play chapter two tonight at both kiosks; backer keys will be on the stream screen.|今晚两机玩第二章，支持者密钥会放直播屏。'))
 x.source('hardware','Actual kiosk hardware and control map|实际试玩机硬件与操作图',image('kiosk-image','assets/t1-04/kiosk.png','Current kiosk hardware. Inspect connected devices and available ports.|当前试玩机硬件，请看已连设备与可用端口。'),image('input-map','assets/t1-04/input-map.png','Public-build control reference. Match the supported input mode to the devices.|公开版本操作参考，请将输入方式匹配实际设备。'),txt('hardware-note','A spare keyboard is available at K2’s desk. K1’s connected keyboard and K2’s controller/USB layout are in the image. Installed builds are currently backer2 on K1 and unpatched public1 on K2.|K2桌有备用键盘。K1已连键盘与K2手柄/USB布局见图。现安装K1是backer2，K2是未修public1。'),field('kiosk-state','Actual installed/tested kiosk configurations|实际安装测试试玩配置',{'K1_build':'backer2','K1_mode':'keyboard','K1_working':False,'K2_build':'public1','K2_mode':'controller','K2_working':False}))
 for k in ['K1','K2']:
  service_at(x,'hardware','kiosk-'+k,'Install changes actual build/input setup together. Test runs that actual kiosk; public1/controller has a genuine input failure, while public1/keyboard and patched1/controller work. Tests do not grant release rights to backer2.|安装同次改实际版本及输入，测试真跑该机；public1手柄真失效，public1键盘及patched1手柄能用。测通不会授backer2公开权。',{'install':option('Install actual build/input|安装实际版本与输入',schema={'build':['public1','patched1','backer2'],'mode':['keyboard','controller']},parameter_record={'resource':'kiosk-state','field':k+'_job','field_map':{'build':k+'_build','mode':k+'_mode'}},set={'kiosk-state':{k+'_working':False}}),'test':option('Run actual kiosk input test|实际跑试玩输入测试',variants=[{'when':{'any':[{'fields':{'kiosk-state':{k+'_build':'public1',k+'_mode':'keyboard'}}},{'fields':{'kiosk-state':{k+'_build':'patched1'}}}]},'set':{'kiosk-state':{k+'_working':True}},'facts':{'input_test':'passed'}},{'when':{},'set':{'kiosk-state':{k+'_working':False}},'facts':{'input_test':'failed'}}])})
 # Physical K1 has no controller. A repaired software build cannot conjure one.
 first_test=x.c['operations']['kiosk-K1/test']['variants'][0]
 first_test['when']={'all':[first_test['when'],{'fields':{'kiosk-state':{'K1_mode':'keyboard'}}}]}
 x.source('supporters','Two private supporter keys and delivery desk|两份私密支持者密钥与交付台',dm('supporter-a','Please put my early-supporter download in this private thread. I am not asking to share it on stream.|我的早期支持下载放本私信，不是要上直播公开。','Supporter A'),dm('supporter-b','Same private delivery as agreed, please. My key is for my account, not the kiosk.|照约私下交就行，密钥给我账号，不给试玩机。','Supporter B'),txt('key-ledger','Supporter A: key A-ELM-71, account early-a. Supporter B: B-REED-29, account early-b. These are fictional private credentials, not public programme text.|A密钥A-ELM-71账号early-a，B密钥B-REED-29账号early-b。均虚构私密凭证，不是公开活动文本。'),field('key-state','Actual private key delivery|实际私密密钥交付',{'a':False,'b':False}))
 service_at(x,'supporters','key-desk','Each delivery sends only that supporter’s key through their existing private thread and returns a delivered receipt. It never updates the public overlay.|各次仅把对应密钥发该支持者原私信并给送达回执，不更新公开叠字。',{n:option('Deliver supporter '+n.upper()+' private key|私下交支持者'+n.upper()+'密钥',set={'key-state':{n:True}},facts={'recipient':'early-'+n,'private_delivery':True}) for n in ['a','b']})
 x.source('access','Recorded walkthrough and caption source|已录讲解与字幕源',txt('walkthrough','W1 is an already-recorded chapter-one public walkthrough, approved for release now. C1 captions match W1/public1; C2 captions describe chapter two. Render captions before uploading the accessible W1 package.|W1是已录第一章公开讲解，现可发。C1对应W1/public1，C2描述第二章；上传无障碍W1前先渲染字幕。'),field('caption-state','Actual rendered caption package|实际字幕导出包',{'source':None,'generated':False}))
 service_at(x,'access','caption-desk','Render a concrete caption source into the actual recorded W1 package.|将具体字幕源渲染进实际已录W1包。',{'render':option('Render selected caption source|渲染所选字幕源',schema={'source':['C1','C2']},parameter_record={'resource':'caption-state','field':'job','field_map':{'source':'source'}},set={'caption-state':{'generated':True}})})
 x.source('stream','Actual trailer and stream overlay queue|实际预告与直播叠字队列',post('overlay','Early supporter keys: A-ELM-71 and B-REED-29. Public chapter-two demo!|早期支持密钥A-ELM-71、B-REED-29，公开第二章试玩！',status='draft'),field('stream-state','Actual trailer and committed stream|实际预告与直播提交',{'trailer':'T2','committed':False}))
 service_at(x,'stream','stream','Replace selects actual trailer clip. Commit snapshots the current overlay and trailer into the outgoing stream; later text edits do not repair an already committed copy automatically.|替换选择实际预告片；提交把当前叠字预告快照送进待播直播，后续改字不自动修已交副本。',{'trailer':option('Replace actual trailer clip|替换实际预告片',schema={'clip':['T1','T2']},parameter_record={'resource':'stream-state','field':'trailer_job','field_map':{'clip':'trailer'}}),'commit':option('Commit actual public stream package|提交实际公开直播包',copy=[{'from':'overlay','to':'stream-overlay','attributes':['text']}],set={'stream-state':{'committed':True}})})
 x.c['lookups']['card/stream'].append(post('stream-overlay','Queued old key-bearing overlay, not yet broadcast.|待播旧含密钥叠字，尚未播出。',status='draft'))
 for n,who in [('a','Host Kestrel'),('b','Host Rowan')]:
  x.source('host-'+n,'Session '+n.upper()+' host and old FAQ|场'+n.upper()+'主持与旧答疑',dm('host-'+n,'Keep my18:00 session. Tell me the actual tested kiosk build/input and public chapter, so I can explain the controls.|保留我18点场，告诉实际测通机版本输入及公开章节，我好讲操作。',who),post('session-'+n,'Public chapter-two controller demo at18:00.|18:00公开第二章手柄试玩。'),old('faq-'+n,'Your public ticket includes the private backer download key.|公开票包含私密支持者下载密钥。'))
