 G(x,'Each host receives usable actual controls|各主持拿可用实际操作','Tell each host their tested kiosk/build/input/public chapter before18:00, distinguishing current setup from a future repair.|18点前分别给主持自己测通机版本输入章节，分清已设置和未来维修。',['host-a','host-b','kiosk-state'],'18:00')
 short=[lookup(k) for k in ['release','hardware','supporters','access','stream','host-a','host-b','download']]
 short += [operate('kiosk-K1','install',build='public1',mode='keyboard'),operate('kiosk-K1','test'),operate('kiosk-K2','install',build='patched1',mode='controller'),operate('kiosk-K2','test'),write('session-a','18:00 at K1: chapter-one public demo, keyboard controls.|18点K1：第一章公开试玩，键盘操作。'),write('session-b','18:00 at K2: chapter-one public demo, repaired controller build.|18点K2：第一章公开试玩，手柄修补版。'),operate('stream','trailer',clip='T1'),write('overlay','Tonight: chapter-one public demo. K1 keyboard; K2 controller. Early-supporter downloads are delivered privately.|今晚第一章公开试玩，K1键盘、K2手柄，早期支持者下载私下交。'),operate('caption-desk','render',source='C1'),operate('download','upload'),operate('key-desk','a'),operate('key-desk','b'),write('faq-a','Correction: public demo tickets cover the chapter-one session, not private supporter keys.|更正：公开试玩票参加第一章场，不含私密支持者密钥。'),write('faq-b','Correction: public demo tickets cover the chapter-one session, not private supporter keys.|更正：公开试玩票参加第一章场，不含私密支持者密钥。'),reply('host-a','K1 is tested on public1/keyboard, chapter one. Your18:00 session is kept.|K1public1键盘版第一章已测通，保留你18点场。'),reply('host-b','K2 is tested on patched1/controller, chapter one. Your18:00 session is kept.|K2patched1手柄版第一章已测通，保留你18点场。'),write('main','Two18:00 chapter-one demos: K1 keyboard, K2 controller. The recorded accessible W1 walkthrough is public; supporter keys are separate private deliveries.|两场18点第一章试玩：K1键盘K2手柄，已录无障碍W1公开，支持密钥另私交。'),operate('stream','commit'),operate('download','preview'),finish('Both chapter-one kiosks are tested, hosts and invitations match, and private keys stayed private. The spoiler-safe stream is committed and accessible W1 is uploaded/checked.|两机第一章均测通，主持邀请一致，密钥私交，无剧透直播包已交，无障碍W1真上传核过。')]
 near=swap(short,'kiosk-K2',operate('kiosk-K2','install',build='public1',mode='controller'),'OPERATE');wrong=swap(short,'overlay',write('overlay','Early keys A-ELM-71 and B-REED-29 — enter them on the public kiosk.|早期密钥A-ELM-71和B-REED-29，公开机输入。'),'WRITE')
 alt=deepcopy(short)
 for idx,a in enumerate(alt):
  if a.get('target')=='kiosk-K2' and a.get('choice')=='install':alt[idx]=operate('kiosk-K2','install',build='public1',mode='keyboard')
  if a.get('target') in ['session-b','host-b','overlay','main'] and a['action'] in ['WRITE','REPLY']:alt[idx]=dict(a,text=T('Both18:00 sessions use tested public1/keyboard on K1 and K2, chapter one. K2 has the available spare keyboard. Supporter keys remain private; accessible W1 is separate.|两场18点均K1/K2测通public1键盘第一章，K2用现有备键盘，密钥仍私交，无障碍W1另发。'))
 return install_plans(x,short,near,g1,wrong,g2,alternative=alt)

