def credits():
 x=newcase('t2-04','Eden','I produce a small choir’s recordings. I keep warmth in a reply without treating a genuine credit mistake as a cute joke.|我制作小合唱团录音，回复温和，但真署名错不当俏皮玩笑。',[('Recital note|音乐会说明','The harmony on the last line was worth the extra take.|最后一句和声值得多录那遍。'),('Private credit check|私下核署名','You translated the lyrics; Sol timed the subtitles. I have separated those roles.|你译歌词，Sol对字幕时码，我把角色分开了。'),('Public correction|公开更正','I credited the wrong person on the film. The new export has the right name and role.|片子署错人，新导出已改对姓名角色。')],'The singer, translator and subtitle editor all did different work|演唱、翻译和字幕，是三个人做的事','It is16:00. By19:00 settle the concert-credit complaint across the public replay, website, printed programme and the two contributor copies already delivered. Keep the approved performance available. Three contributors requested their final role wording in their private threads; the actual rendered credits, print and delivered copies must agree. Fix our old public apology, which blamed the translator for singing the wrong words.|现在16:00，19点前处理音乐会署名投诉，公开回放、网站、纸节目单、两份已交贡献者副本都改。已获准演出继续保留。三位贡献者要在原私信拿自己最终角色措辞，实际渲染、纸品、副本一致。旧公开致歉错怪翻译唱错词，也改掉。','Open the full complaint, stage roster, translator agreement, subtitle edit chain, actual print job, replay export and the two separately delivered contributor packs.|打开完整投诉、舞台名单、翻译约定、字幕编辑链、真实印刷任务、回放导出及两份独立已交贡献包。',180)
 x.source('complaint','Full complaint and old apology|完整投诉与旧致歉',post('main','Our choir film is up; everyone in the credits sang on stage.|合唱片上线，署名的人都上台唱了。'),comment('complaint','“Singing with a dictionary” was a joke about translating. I did not sing, and blaming my voice in the apology is a bit much.|“抱字典唱歌”是翻译的玩笑，我没唱，致歉里怪我的嗓子就过了吧。','Translator Fern'),comment('complaint-parent','Fern translated the lines, Lark sang, and Sol placed the captions. The performance itself is fine.|Fern译词，Lark唱，Sol做字幕时码，演出本身没问题。','Stage manager','complaint'),old('old-apology','Sorry Fern sang the wrong words; our translator was the performer.|抱歉Fern唱错词，我们翻译也是演唱。'))
 x.source('roster','Stage roster and singer’s requested wording|舞台名单及歌手所要措辞',txt('roster','Stage singer public alias Lark; private legal name stays off programme. Fern did not sing. Sol edited/timed subtitles but did not translate. All three accept public role-only credit if a privacy-safe edition omits names.|演唱公开名Lark，真名不放节目单；Fern未唱，Sol编排时码而非翻译。保护隐私版本若不署名，三人均接受公开仅写角色。'),dm('singer-dm','Please put my final wording here as “Lark — vocal performance”, not my legal name. Role-only is okay for the privacy-safe edition.|最终措辞本串给我：“Lark——演唱”，不用真名，隐私版只写角色也行。','Lark'))
 x.source('translation','Actual translation licence and contributor request|实际翻译许可与本人请求',txt('translation-terms','Fern’s translation TL1 is licensed for this choir film, its programme and the two agreed contributor copies only. Credit translation, not vocal performance. New commercial reuse requires a separate grant; this correction supplies none.|Fern译文TL1只许本团影片节目单及两份已约贡献包，署翻译不是演唱；新商业复用另要许可，本次更正不新增。'),dm('translator-dm','Send me the final translation-credit line in this thread. I am not asking for the valid performance to be withdrawn.|最终翻译署名本串给我，我不是要撤有效演出。','Fern'),post('licence-register','Fern: vocalist; translation may be reused commercially by anyone.|Fern演唱，译文任何人可商业复用。'))
 x.source('subtitles','Actual subtitle authorship chain|实际字幕作者链',txt('subtitle-chain','TL1 words: Fern. Timecodes/layout SC1: Sol. Vocal recording V1: Lark. Captions and end card are separate burned layers in the actual replay, while website credit is another editable page.|TL1文字Fern，SC1时码排版Sol，V1演唱Lark。字幕和片尾卡是回放独立烧字层，网页署名是另一可改页。'),dm('editor-dm','Please send my exact final role here too: subtitle timing/editing, not translation.|我的最终角色也请本串给：字幕时码编辑，不是翻译。','Sol'),post('subtitle-credit','Translation and vocals: Sol.|翻译演唱Sol。'),post('video-credit','Vocalist: Fern. Subtitle editor: Lark.|演唱Fern，字幕编辑Lark。'),post('web-credit','All words, vocals and captions by Fern.|词演唱字幕均Fern。'))
 x.source('print','Actual programme plate and print receiver|实际节目单印版及接收台',post('programme-plate','Vocal: Fern; translation: Sol; subtitle timing: Lark.|演唱Fern，翻译Sol，字幕时码Lark。'),post('printed-programme','Vocal: Fern; translation: Sol; subtitle timing: Lark.|演唱Fern，翻译Sol，字幕时码Lark。'),field('print-state','Actual programme print and receiving|实际节目单印刷接收',{'replaced':False,'received':False}))
 service_at(x,'print','printer','Replace prints the corrected programme plate. Receive gets that actual print into the foyer distribution desk, independently of the online replay.|替换印正确印版，接收将真纸品交门厅分发台，与线上回放独立。',{'replace':option('Replace actual programme print job|替换真实节目单印刷',copy=[{'from':'programme-plate','to':'printed-programme','attributes':['text']}],set={'print-state':{'replaced':True}}),'receive':option('Receive programme at foyer desk|门厅台实收节目单',requires={'fields':{'print-state':{'replaced':True}}},set={'print-state':{'received':True}})})
 x.source('replay','Actual replay render, publication and preview|实际回放渲染发布及预览',post('rendered-film-credit','Old burned role labels.|旧烧录角色署名。'),post('public-film-credit','Old burned role labels.|旧烧录角色署名。'),field('replay-state','Actual rendered/published replay|实际导出发布回放',{'rendered':False,'published':False,'checked':False}))
 service_at(x,'replay','replay','Render regenerates actual burned credits from current video/subtitle layers. Replace publishes that rendered file; preview checks the installed public file. Media content is a structured fictional video record, not an included movie file.|渲染按当前片尾/字幕层真生成烧字，替换发导出文件，预览查已装公开文件。视频是结构化虚构记录，不附真实电影文件。',{'render':option('Render corrected burned credit layers|渲染正确烧录署名层',copy=[{'from':'video-credit','to':'rendered-film-credit','attributes':['text']},{'from':'subtitle-credit','to':'rendered-subtitle-credit','attributes':['text']}],set={'replay-state':{'rendered':True}}),'replace':option('Replace actual public replay|替换实际公开回放',requires={'fields':{'replay-state':{'rendered':True}}},copy=[{'from':'rendered-film-credit','to':'public-film-credit','attributes':['text']},{'from':'rendered-subtitle-credit','to':'public-subtitle-credit','attributes':['text']}],set={'replay-state':{'published':True}}),'preview':option('Inspect actual public replay credits|检查实际公开回放署名',set={'replay-state':{'checked':True}},inspect=['public-film-credit','public-subtitle-credit'])})
 x.c['lookups']['card/replay'] += [post('rendered-subtitle-credit','Old subtitle role.|旧字幕角色。'),post('public-subtitle-credit','Old subtitle role.|旧字幕角色。')]
 for n,who in [('a','Lark'),('b','Fern')]:
  x.source('copy-'+n,'Already delivered '+who+' contributor copy|已交'+who+'贡献者副本',post('contributor-'+n,'Old delivered credit file.|旧已交署名文件。'),post('contributor-subtitle-'+n,'Old delivered subtitle role layer.|旧已交字幕角色层。'),field('copy-'+n+'-state','Actual contributor replacement '+n.upper()+'|实际贡献副本替换'+n.upper(),{'replaced':False,'received':False}))
  service_at(x,'copy-'+n,'copy-'+n,'Replace sends this recipient the newly rendered film with corrected burned layers. Receipt retrieves that recipient’s actual replacement acknowledgement. These are separate already-delivered files, not live links.|替换把新渲染更正烧字片送此收件人，回执取实际换件确认。各自是已交文件，不是实时链接。',{'replace':option('Replace this delivered contributor file|替换此已交贡献文件',copy=[{'from':'rendered-film-credit','to':'contributor-'+n,'attributes':['text']},{'from':'rendered-subtitle-credit','to':'contributor-subtitle-'+n,'attributes':['text']}],set={'copy-'+n+'-state':{'replaced':True}}),'receipt':option('Get actual contributor replacement receipt|取真实贡献者换件回执',requires={'fields':{'copy-'+n+'-state':{'replaced':True}}},set={'copy-'+n+'-state':{'received':True}})})
 g1=G(x,'Understand credit complaint and actual roles|理解署名投诉及真实角色','Fern’s dictionary joke refers to translating, not singing. Credit Lark vocal, Fern translation, Sol subtitle timing/editing; keep private legal name out. Do not treat the valid performance as defective.|字典玩笑说翻译非演唱，署Lark演唱Fern翻译Sol字幕时码编辑，真名不公开，别把有效演出说成有问题。',['complaint','complaint-parent','roster','translation-terms','subtitle-chain'],'19:00',alternative='All three accept public role-only labels in a privacy-safe edition; actual role distinction must remain.|隐私版三人均接受公开只写角色，但实际角色区别须保留。')
 g2=G(x,'No invented reuse grant|不编复用许可','Correct licence-register to TL1’s actual choir-film/programme/two-copy scope; credit correction does not grant anyone commercial reuse.|许可登记按TL1本团片节目单两副本范围，改署名不授任何人商业复用。',['licence-register','translation-terms'],'19:00')
 G(x,'Current public layers and main|当前公开各层主帖','Correct video-credit, subtitle-credit, web-credit and main with the actual distinct roles. A webpage fix does not repair burned file layers.|按真实角色改片尾、字幕、网页及主帖；改网页不改烧录层。',['video-credit','subtitle-credit','web-credit','main'],'19:00')
 G(x,'Actual rendered/published/checked replay|实际渲染发布核回放','Render both actual burned layers, replace public film and inspect it. Keep the approved performance available; local script edits alone are insufficient.|真渲染两烧字层，替公开片并查，保留获准演出，只改本地脚本不够。',['rendered-film-credit','rendered-subtitle-credit','public-film-credit','public-subtitle-credit','replay-state'],'19:00')
 G(x,'Actual printed programme|真实纸节目单','Correct programme-plate, replace print job and receive actual correct paper at foyer desk.|改节目印版、替印刷任务并门厅实收正确纸品。',['programme-plate','printed-programme','print-state'],'19:00')
 G(x,'Both already-delivered contributor files|两份已交贡献文件','Replace both independent contributor copies from corrected render and obtain actual replacement receipts. Live replay change does not alter their files.|用正确渲染替两份独立贡献者副本并取真回执，实时回放变更不改其文件。',['contributor-a','contributor-b','contributor-subtitle-a','contributor-subtitle-b','copy-a-state','copy-b-state'],'19:00')
 G(x,'Requested wording and false old apology|所要措辞及旧错误致歉','Send each contributor their exact final role wording privately as requested, and correct old-apology that blamed translator’s voice. No needless reapproval is required.|各人私下按请求得准确最终角色措辞，改旧致歉怪翻译嗓子，不多审批。',['singer-dm','translator-dm','editor-dm','old-apology'],'19:00')
 credit='Vocal performance: Lark. Translation TL1: Fern. Subtitle timing/editing SC1: Sol.|演唱Lark，TL1翻译Fern，SC1字幕时码编辑Sol。'
 short=[lookup(k) for k in ['complaint','roster','translation','subtitles','print','replay','copy-a','copy-b']]+[reply('singer-dm','Final credit: Lark — vocal performance. Your legal name is left out.|最终署名Lark——演唱，不放真名。'),reply('translator-dm','Final credit: Fern — translation TL1. The performance is staying; I am changing the credits to that role.|最终署名Fern——TL1翻译，演出保留，我正在按这个角色改署名。'),reply('editor-dm','Final credit: Sol — subtitle timing/editing SC1, separate from Fern’s translation.|最终署名Sol——SC1字幕时码编辑，与Fern翻译分开。'),write('video-credit',credit),write('subtitle-credit',credit),write('web-credit',credit),write('main','Our concert replay keeps the approved performance. Lark sings, Fern translated TL1, and Sol timed/edited SC1 captions.|演出按获准版本保留，Lark演唱、Fern译TL1、Sol做SC1字幕时码编辑。'),operate('replay','render'),operate('replay','replace'),operate('replay','preview'),write('programme-plate',credit),operate('printer','replace'),operate('printer','receive'),operate('copy-a','replace'),operate('copy-b','replace'),operate('copy-a','receipt'),operate('copy-b','receipt'),write('old-apology','Correction: Fern translated the words and did not sing. Lark’s performance was valid; the mistake was our role credit, not the translator’s voice.|更正：Fern译词没唱，Lark演出有效。错在我方角色署名，不是翻译的嗓子。'),write('licence-register','TL1 translation by Fern: this choir film, its programme and two agreed contributor copies. New commercial reuse needs a separate grant.|TL1Fern翻译，只限本团片节目单两份约定贡献副本，新增商业复用另需许可。'),finish('The actual replay, website, printed programme and both replaced contributor copies distinguish the three roles; old apology and licence record are corrected.|真实回放网站纸节目单两替换副本均分清三角色，旧致歉与许可登记已改。')]
 near=swap(short,'video-credit',write('video-credit','Vocal performance: Fern. Translation: Lark. Subtitles: Sol.|演唱Fern、翻译Lark、字幕Sol。'),'WRITE');wrong=swap(short,'licence-register',write('licence-register','Fern’s translated lyrics are now cleared for any commercial remix.|Fern译词现许可任何商业混剪。'),'WRITE')
 alt=deepcopy(short)
 for idx,a in enumerate(alt):
  if a.get('target') in ['video-credit','subtitle-credit','web-credit','programme-plate'] and a['action']=='WRITE':alt[idx]=dict(a,text=T('Credits: vocal performer; lyric translator; subtitle timing/editor. Role-only edition agreed by all three contributors.|贡献：演唱者、歌词翻译、字幕时码编辑。三人同意的仅角色署名版。'))
 return install_plans(x,short,near,g1,wrong,g2,alternative=alt)

