def birdcount():
 x=newcase('t3-04','Rory','I curate community nature photos. I separate an honest duplicate from a false observation, and give volunteers concrete route instructions.|我整理社区自然照片，真实重复和假观察分开，给志愿者具体路线。',[('Photo caption|照片说明','Same heron, two cameras. Still a lovely pair of pictures.|同只鹭，两台相机，照片还是都好看。'),('Private count note|私下计数','We need the capture time, not the upload time, before counting another event.|加一条事件前先看拍摄时间，不看上传时间。'),('Route correction|路线更正','The bus stops at West gate. The last eight minutes are on foot.|车停西门，最后八分钟步行。')],'A bird count can change without losing a bird|同一只鸟被算了两遍，观察却都是真的','It is16:00. By19:00 correct the survey count and actually dispatch today’s agreed North foot survey and the threshold-triggered South team. Keep both photographers’ credit. The minibus is shared; count distinct observation events, not filenames, before choosing its destination. Repair the two separate old count answers too.|现在16:00，19点前改调查计数，真发今天已约北点步行调查及达到阈值才去的南点组。保留两位摄影者署名，客车共享，先数独立观察事件不是文件名，再定车去处，两条独立旧计数答复也改。','Open the three source observation registers, camera-clock correction, deployment rule, site access, volunteers, photographer-credit thread and dispatch board.|打开三处来源观察登记、相机时钟修正、派队规则、点位通行、志愿者、摄影署名串和派车台。',180)
 obs=[('a','A17','North','16:10','camera A UTC+0','Event N7','Photographer Ada'),('b','B44','North','17:10','camera B clock one hour fast','Event N7','Photographer Bo'),('c','C02','South','16:35','camera C correct local clock','Event S8','Photographer Ada')]
 for n,rid,site,clock,clocknote,event,person in obs:
  x.source('observation-'+n,'Independent source register '+rid+'|独立来源登记'+rid,txt('photo-'+n,'Recorded yesterday. File '+rid+': '+site+' reed bed, displayed capture '+clock+', '+clocknote+'. Upload IDs differ. Original sequence records the same bent reed/one-wing pose in A17/B44; C02 is a later South bank shot.|文件'+rid+'：昨天在'+site+'苇床，显示拍摄'+clock+'，'+clocknote+'。上传号不同；原序列A17/B44同弯苇和单翅姿态，C02是后来南岸。'),field('observation-'+n+'-state','Actual curator event classification|实际编目事件归类',{'event':'unclassified'}))
  service_at(x,'observation-'+n,'source-'+n,'This independent source register holds one curatorial event classification; changing it does not change the other repositories.|此独立来源库各有一份编目事件归类，改它不改其他库。',{'classify':option('Classify this source observation event|归类此来源观察事件',schema={'event':['N7','S8','new_event']},parameter_record={'resource':'observation-'+n+'-state','field':'classification','field_map':{'event':'event'}})})
 x.source('clock','Actual camera correction and baseline event|实际相机时钟修正与基线事件',txt('clock','All observations in this register were captured yesterday. Camera B was exactly60 minutes fast for B44. A17 and corrected B44 share North16:10 event N7. C02 is South16:35 S8. Separately verified baseline S0 is South14:00 and remains a distinct event. No photographer fabricated a bird; duplicate photographs retain separate authorship.|本登记里的观察均拍于昨天，B相机B44快整60分，修正后与A17同北点16:10N7；C02南点16:35S8，另已核南点14:00S0仍独立。无人造假，同事件照片保留各自作者。'))
 x.source('rule','Actual count threshold and recomputation service|实际计数阈值及重算服务',txt('rule','Today’s deployment uses the validated observations from yesterday. North has an already promised one-person foot check irrespective of threshold. A site with at least two distinct events gets the two-person minibus survey. There is only one two-person team and one bus. Recompute counts from current source classifications plus baseline S0.|今天按昨天已核观察派组，北点无论阈值均有已约一人步行检查；至少两独立事件的点得两人客车组。只有一组两人、一车。按当前来源归类加S0重算。'),field('count-state','Actual distinct event counts|实际独立事件数',{'North':2,'South':2}),post('north-map','North has two new events; minibus team here.|北有两个新事件，客车组来。'),post('south-map','South remains optional; count not checked.|南点可选，未核计数。'))
 service_at(x,'rule','count','Recompute uses the recorded event IDs; A and B with the same N7 count once, S0 plus C/S8 count twice.|重算按记录事件号，A/B同N7只计一，S0加C/S8计二。',{'recompute':option('Recompute distinct site counts|重算点位独立事件数',variants=[{'when':{'fields':{'observation-a-state':{'event':'N7'},'observation-b-state':{'event':'N7'},'observation-c-state':{'event':'S8'}}},'set':{'count-state':{'North':1,'South':2}}},{'when':{},'set':{'count-state':{'North':2,'South':2}}}],inspect=['count-state'])})
 x.source('access','Site access records and current gate service|点位通行记录与当前门控',txt('access','North foot check17:00–17:20 uses the public North path. South survey18:15–18:45 accepts the West gate drop plus8-minute walk; that foot path and drop are confirmed open until19:00. East vehicle gate was last checked15:00 and needs a current gate check before use. Nobody needs to test East if choosing confirmed West.|北步行17:00–17:20走北公共路。南18:15–18:45可西门下车后走八分钟，此步道下车点已确认开到19点。东车门上次15点核，使用前须当前门控核验；选已确认西门不用测东。'),field('access-state','Actual current East gate check|实际当前东门核验',{'checked':False,'east_open':None}))
 service_at(x,'access','gate','Current gate check reads the actual East vehicle barrier, not the older schedule.|当前核验读实际东车闸，不是旧时表。',{'check':option('Check actual East vehicle gate|核当前东车门',set={'access-state':{'checked':True,'east_open':False}},facts={'east_open':False,'reason':T('Vehicle barrier closed for maintenance; West foot-access route remains available.|车闸检修关，西门步行入口仍可用。')})})
 x.source('volunteers','Accepted North/South volunteers|已接受北南志愿者',dm('north-dm','I can do the promised North foot check17:00–17:20. Please do not cancel that just because a count changes.|我能做已约北步行17:00–17:20，别计数一变就取消。','North volunteer'),dm('south-dm','The two of us can take the bus for South18:15–18:45 if the two-event rule is met. We can walk eight minutes from West.|两人可坐车去南18:15–18:45，前提两事件规则达标，西门走八分钟可接受。','South team'))
 x.source('credits','Two photographer conversations and old count claims|两摄影者会话与旧计数宣称',dm('ada-dm','Please keep my photo credit even if another camera caught the same bird. Tell me which events my files now belong to.|别因别台拍同只鸟就去我署名，告诉我文件归哪个事件。','Photographer Ada'),dm('bo-dm','My camera clock was wrong, not my photo. Let me know the corrected event ID so I can fix my own caption.|我时钟错，不是照片假，给修正事件号我好改自己的说明。','Photographer Bo'),old('old-north','Two filenames prove two independent North sightings.|两个文件名证明北点两独立观察。',parent='north-count-thread'),old('old-fraud','Bo’s duplicate means the sighting was made up.|Bo重复照片说明观察造假。',parent='photo-credit-thread'),comment('north-count-thread','How many North events?|北点几事件？','North reader'),comment('photo-credit-thread','Who took this photo?|谁拍的？','Credit reader'))
 x.source('dispatch','Actual site assignments, bus and driver order|实际点位派组客车及司机单',field('dispatch-state','Actual dispatch state|实际派遣状态',{'North':None,'South':None,'bus_booked':False,'route':'East','dispatched':False}),dm('driver-dm','I need the actual South drop point and arrival target. A general “take them to the birds” message is not a route.|我要真南点下车处和到达目标，泛说带他们看鸟不是路线。','Driver'))
 service_at(x,'dispatch','dispatch','Assign each independently supervised site, reserve the one bus with a concrete drop, then dispatch the actual job. Changing a route after the current gate check is a real order correction, not another bus booking.|各点独立督导派组，按具体下车点订唯一客车，再真发车。查门后改路是真单更正，不是再订一车。',{'North':option('Assign North foot volunteer|派北点步行志愿者',set={'dispatch-state':{'North':'foot_volunteer'}}),'South':option('Assign South two-person team|派南点两人组',set={'dispatch-state':{'South':'two_person_team'}}),'book':option('Reserve one actual minibus/drop|订一辆实际客车及下车点',schema={'drop':['East','West']},parameter_record={'resource':'dispatch-state','field':'bus_job','field_map':{'drop':'route'}},set={'dispatch-state':{'bus_booked':True}}),'reroute':option('Correct actual booked drop to West|真改单改西门下车',set={'dispatch-state':{'route':'West'}}),'send':option('Actually dispatch accepted survey work|实际发出已受理调查任务',variants=[{'when':{'fields':{'dispatch-state':{'North':'foot_volunteer','South':'two_person_team','bus_booked':True,'route':'West'},'count-state':{'North':1,'South':2}}},'set':{'dispatch-state':{'dispatched':True}},'facts':{'North_foot_order':'sent','South_bus_order':'sent','drop':'West','arrival':'18:05','South_walk_arrival':'18:13'}},{'when':{},'facts':{'dispatched':False,'reason':T('Counts, accepted teams or safe bus route do not match an executable order.|计数已接组或安全车路不符可执行单。')}}])})
