 x.source('students','Student release approvals and private papers|学生展示许可及私有材料',txt('student-scope','Student works clock C1 and weather wheel W2 already have valid public display approval. Their full release forms and parent contact records are staff-only. Current organiser may operate approved final display files but cannot grant or widen any student release.|时钟C1和天气轮W2已有效获准公开展示，完整许可表家长联络仅教职工。现组织者可运营已批成品，不可批或扩大任何学生许可。'),field('student-state','Actual private paperwork access|实际私有材料访问',{'ren-old':True,'cedar-lio':False}))
 service_at(x,'students','student-access','Remove expired organiser access to private release paperwork. A display-role transfer does not grant current organiser access to these papers.|移前组织者过期私有许可材料访问，展陈角色转移不授现组织者这些材料。',{'remove-old':option('Remove expired old paperwork access|移旧过期材料访问',set={'student-state':{'ren-old':False}})})
 for n,operator in [('print','Print operator Gia'),('wall','Digital-wall operator Finn')]:
  x.source('job-'+n,'Actual external '+n+' job and operator|实际外部'+n+'任务及操作人',field('job-'+n+'-state','Actual '+n+' ownership/credentials|实际'+n+'所有权凭证',{'pending_old_invite':True,'new_invited':False,'accepted':False,'owner':'ren-old','old_collaborator':True,'old_token_active':True,'new_token_ready':False}),dm('operator-'+n,'The18:00 display job stays booked. Send the new operational contact/account and tell me which approved final files I should use; the programme’s old author line is not an instruction to change owner.|18点展陈任务保留。给新运营联系人账号和应使用的已批成品文件，节目单旧作者行不是换所有权指令。',operator))
