 x.source('shots','Two committed shot outputs and old preview|两份既有镜头交付与旧预览',txt('shot-list','Output M: the actual repeated measured comparison using supplied protocol; no universal road-speed promise. Output F: static clothes-only frame, faces excluded, no inferred speed result. Both clients already commissioned these distinct outputs.|M按所给重复测量协议的真对比，不许通用公路速度承诺；F静态仅服装不含脸，不据此推速度，两客户已分别约这两项。'),old('old-preview','The courtyard moving ride will prove the suit is faster on every public road.|庭院动态骑行会证明这衣服每条公路都更快。'),field('production-state','Actual capture and exported proof states|实际拍摄与导出证明状态',{'rig_setup':False,'measured':False,'method':None,'measurement_exported':False,'measurement_claim':None,'fashion_captured':False,'fashion_frame':None,'raw_card_removed':False}))
 x.source('protocol','Accepted measurement and export controller|已接受测量协议与导出控制',txt('protocol','Use matched rider/bike, paired repeated runs in the chosen controlled protocol. Closed-track result may be described only as closed-track comparison. Indoor-trainer result may be described only as trainer resistance comparison, not on-road speed. The supplied controller records the matched repeat-run set; no outside sports/science facts needed.|所选受控协议用相同骑手车及成对重复跑，封闭场只称封闭场对比，室内台只称台阻力对比不称公路速度。所给控制器记录配对重复组，不需外部运动科学知识。'))
 service_at(x,'protocol','production','Set up the actual borrowed timing rig before measuring. Capture static clothing in courtyard, then run the booked measured protocol after accepted transport. Export chooses the claim attached to real measured data; it cannot turn one protocol into another.|先装实际借用计时架再测，庭院拍静态后按已接运输到测量点跑。导出选择真实数据附带结论，不能把一种协议变另一种。',{'setup':option('Set up actual paired timing rig|装实际配对计时架',set={'production-state':{'rig_setup':True}}),'capture':option('Capture agreed static clothing output|拍已约静态服装输出',schema={'frame':['clothes_only','full_face'],'movement':['static','moving']},parameter_record={'resource':'production-state','field':'fashion_job','field_map':{'frame':'fashion_frame'}},variants=[{'when':{'time':{'minimum':30,'maximum':50},'fields':{'location-state':{'fashion':True}}},'set':{'production-state':{'fashion_captured':True}},'facts':{'captured':True}},{'when':{},'facts':{'captured':False}}]),'measure':option('Run actual booked repeated measurement|实际跑已约重复测量',variants=[{'when':{'time':{'minimum':60,'maximum':80},'fields':{'location-state':{'measurement':'closed_track'},'transport-state':{'destination':'closed_track','ordered':True},'production-state':{'rig_setup':True}}},'set':{'production-state':{'measured':True,'method':'closed_track'}},'facts':{'paired_runs':4,'protocol':'closed_track','observed_difference':'3 percent in this controlled set'}},{'when':{'time':{'minimum':45,'maximum':65},'fields':{'location-state':{'measurement':'indoor_trainer'},'transport-state':{'destination':'indoor_trainer','ordered':True},'production-state':{'rig_setup':True}}},'set':{'production-state':{'measured':True,'method':'indoor_trainer'}},'facts':{'paired_runs':4,'protocol':'indoor_trainer','observed_difference':'2 percent resistance in this controlled set'}},{'when':{},'facts':{'measured':False}}]),'export':option('Export actual measurement with scoped claim|导出真测量及范围结论',schema={'claim':['closed_track','indoor_trainer','public_road']},parameter_record={'resource':'production-state','field':'measurement_export','field_map':{'claim':'measurement_claim'}},set={'production-state':{'measurement_exported':True}}),'remove-card':option('Remove our raw footage card from borrowed camera|从借相机取回自有原素材卡',set={'production-state':{'raw_card_removed':True}})})
 for n,person in [('a','Rider Ana'),('b','Rider Ben')]:
  x.source('rider-'+n,person+' actual availability/consent|'+person+'实际可用与同意',dm('rider-'+n,'I agreed to the paired controlled comparison and static clothes-only photos, not public-road filming or face close-ups. Tell me the actual sequence/site once booked. I can do the courtyard first, then either accepted test slot.|我同意配对受控比较和静态仅服装照，不拍开放公路或脸特写。订后给实际顺序地点，可先庭院再任一已接测试时段。',person))
 x.source('loans','Two independent kit owners and receiving windows|两位独立器材主人及收件窗口',txt('loans','Timing rig belongs to club tech desk R: actual receiving17:25–17:30. Camera belongs to camera desk C: actual receiving18:05–18:10. Both onward users are already waiting on these confirmed windows. Our memory card belongs to the host and contains private raw rider frames; remove it before returning camera. The rig and camera are separate items/owners.|计时架归技术台R，17:25–17:30实收；相机归相机台C，18:05–18:10实收。下位用户均已约等这些窗口。自有卡含私人骑手原画，先取卡再还相机。架相机不同物不同主人。'),field('loan-state','Actual kit custody|实际器材保管',{'rig_received':False,'camera_received':False}))
