 short=[lookup(k) for k in ['permits','shots','protocol','rider-a','rider-b','loans','transport','clients']]+[operate('locations','measurement',site='closed_track'),operate('locations','fashion'),operate('transport','order',destination='closed_track'),reply('rider-a','Booked: static clothes-only courtyard16:30 first, then closed-track paired runs17:00–17:20. Runner transfers us and the shared camera; no public-road filming.|已订先16:30庭院静态仅服装，再17:00–17:20封闭场配对跑，跑腿送人与共享相机，不拍开放公路。'),reply('rider-b','Same accepted sequence: courtyard16:30 static clothes-only, then closed-track17:00–17:20. Faces stay out of the clothing output.|同已接顺序，16:30庭院静态仅服装，再17:00–17:20封闭场，服装输出不含脸。'),operate('production','setup'),wait(30),operate('production','capture',frame='clothes_only',movement='static'),wait(60),operate('production','measure'),operate('production','export',claim='closed_track'),operate('proofs','M'),operate('proofs','F'),ask('measurement-client','approve','The actual paired-run proof is in your M review space with the closed-track-only description. Please review that exact snapshot.|实际配对跑证明已到M空间，仅封闭场描述，请审这份确切快照。'),ask('fashion-client','approve','The actual static clothes-only proof is in your F space, with no face or speed claim. Please review that snapshot.|实际静态仅服装证明到F空间，不含脸无速度宣称，请审此快照。'),operate('proofs','release-M'),operate('proofs','release-F'),write('old-preview','Correction: moving public-road filming is cancelled. This comparison uses paired closed-track runs only; the courtyard output is separate static clothes-only photography.|更正：开放公路动态拍摄取消，对比仅用配对封闭场跑，庭院另做静态仅服装照。'),operate('production','remove-card'),wait(85),operate('rig-return','return'),wait(125),operate('camera-return','return'),finish('Both clients approved and received the actual scoped outputs. Timing rig and empty-card-slot camera were physically returned in their separate windows; raw rider footage stays on our card.|两客户已批并实收范围内输出，架与空卡槽相机分别在各自窗口真还，骑手原素材留自有卡。')]
